const PAGE_LANG='en';
let MODULES=[
{id:1,emoji:'📊',title:'Understanding the Metric: Attendance',desc:'The two measures behind the numbers — Back Office Attendance and Classroom Presence — the red and yellow absence types, the five risk groups, what HPR and LPR mean, and the three things that put you on our list.',obj:'Understand how attendance and presence are measured, know which risk group each of your students is in, know exactly what would put you on our list — and separate the causes you can influence from the ones you cannot.',color:'#D3FF5F',
 sections:[
  {t:'📐 Two Ways We Measure This',cards:[
    {type:'text',b:'A student can be <strong>missing from the lesson</strong>, or <strong>present but checked out</strong> — two completely different problems, so we use 2 measures:'},
    {type:'table',h:'The two measures',head:['Measure','The question it answers','Where it comes from'],rows:[
      ['🙋 <strong>Attendance (BO)</strong>','Did the student come?','Back Office — the lesson was scheduled, and the student either showed up or didn\'t'],
      ['🎥 <strong>Classroom Presence</strong>','When they came, were they really there?','Classroom Data — how much of the lesson the student was actually in the room for'],
    ]},
    {type:'tip',txt:'Why we need both: Back Office is the only place that knows a lesson was <em>supposed</em> to happen. Without it, a student who never showed up leaves no record at all — the absence is invisible. Classroom on its own only ever measures how engaged the students who <em>did</em> turn up were.'},
  ]},
  {t:'🧮 How Classroom Presence Is Calculated',cards:[
    {type:'flow',steps:[
      {ic:'⏱️',h:'1 · Connected time',b:'For every lesson, we compare how long the student was actually connected against the lesson\'s length. Stay the whole lesson → 100%. Leave halfway → about 50%. Ten minutes of a sixty-minute lesson → about 17%.',color:'blue'},
      {ic:'✅',h:'2 · The 50% line',b:'A student only counts as <em>Present</em> for that lesson above 50%. Connecting for ten minutes and disappearing is not attendance, and it isn\'t counted as one.',color:'coral'},
      {ic:'📊',h:'3 · 30-day average',b:'Their Classroom Presence is the average of that across their lessons in the last 30 days — calculated per group and per course, so a student in two of your courses is measured separately in each.',color:'green'},
    ]},
    {type:'good',txt:'Lessons never recorded in Classroom (about 1%) still count for BO Attendance — a real absence never disappears just because Classroom missed it.'},
    {type:'hi',h:'Who is counted',b:'Not every student appears in your numbers.<br><br>A student is only included once they have <strong>at least 3 scheduled lessons</strong> and <strong>a lesson in the last 14 days</strong>. So a single lesson can never swing your percentage, and students who left long ago stop distorting it.<br><br>If a student you teach is missing from your list, this is almost always why.'},
  ]},
  {t:'🟡🔴 Two Kinds of Absence',cards:[
    {type:'text',b:'On the Back Office side, an absence is not just an absence — treating an announced absence the same as a student who vanished without a word would be unfair, so we don\'t.'},
    {type:'img',src:'Images/image8_ENG.png'},
    {type:'doavoid',left:{h:'🟡 Yellow — announced or justified',items:['The family gave a reason in advance','A health issue, vacation, technical or scheduling problem, etc.','A situation the family is actively managing']},right:{h:'🔴 Red — no warning at all',items:['The student disappeared without a word','Nobody followed up before the next lesson','The kind of absence we want to eliminate entirely']}},
    {type:'text',b:'Which one you select, and what you do next, is Module 6 — that module is the instruction manual for this page.'},
  ]},
  {t:'🚦 Your Five Risk Groups',cards:[
    {type:'text',b:'Put Attendance and Classroom Presence together and every student lands in one of five groups — in whichever group the <strong>worse</strong> of the two signals puts them, so nobody slips through when the signals disagree.'},
    {type:'text',b:'Read the two middle columns as <strong>alternatives, not conditions</strong>: a group is triggered by either the absences or the presence — whichever is worse. A student with no absences at all can sit in ALERT on presence alone, and a student with perfect presence can sit in CRITICAL on a single unexplained absence.'},
    {type:'table',h:'Risk groups',tone:'danger',head:['Group','Back Office absences','Classroom Presence','What it means'],rows:[
      ['🔴 <strong>CRITICAL</strong>','One or more red, or four or more yellow','—','An absence nobody explained, or absences piling up — we don\'t know whether this student is still with us'],
      ['🟠 <strong>HIGH RISK</strong>','—','Below 50%','Turns up, but is barely in the room'],
      ['🟡 <strong>ALERT</strong>','2–3 yellow','50% – 74.99%','Missing lessons the family explained — or in the room for only half of them'],
      ['🔵 <strong>WATCH</strong>','—','75% – 84.99%','Present, but not fully engaged — the drift is just starting'],
      ['🟢 <strong>Healthy</strong>','No red, at most 1 yellow','≥ 85%','Consistent presence and engagement'],
    ]},
    {type:'warnbox',h:'A yellow absence is not a black mark. It is proof you did your job.',b:'One announced absence leaves a student Healthy. It takes two before a student is even in ALERT, and that is deliberate: the point where a drifting student can still be brought back is the second absence, which is exactly what Module 6 is about.<br><br>An unexplained (red) absence is different, and it counts immediately — not because red is worse behaviour, but because nobody knows what happened.'},
  ]},
  {t:'📈 HPR and LPR — What Your Numbers Actually Mean',cards:[
    {type:'text',b:'These are measured on <strong>Classroom Presence</strong> (not on a single flat attendance percentage):'},
    {type:'twocol',left:{h:'📈 HPR — High Presence Rate',items:['Share of your students at 75% or above — that is everyone in 🟢 Healthy or 🔵 WATCH','Higher is better']},right:{h:'📉 LPR — Low Presence Rate',items:['Share of your students below 50% — everyone in 🟠 HIGH RISK','Lower is better'],plain:true}},
    {type:'text',b:'Because the two rates are drawn straight from the groups above, the table and your card can never disagree: <strong>HPR is Healthy plus WATCH, LPR is HIGH RISK.</strong>'},
    {type:'text',b:'The bar held across all regions: <strong>LPR at or below 25.5%</strong> · <strong>HPR at or above 49.5%</strong>.'},
    {type:'hi',h:'The real goal isn\'t a rate — it\'s two outcomes',b:'🔴 <strong>Eliminate unexcused (red) absences.</strong> A red absence means a student vanished and nobody followed up — that should stop being possible.<br><br>🟡 <strong>Eliminate the drop-off that begins at the second excused absence.</strong> No student should quietly disappear, and none should be lost to two absences nobody answered.'},
  ]},
  {t:'🧭 The Practical Payoff',cards:[
    {type:'text',b:'The two measures point at different problems, with different fixes — that\'s the reason we split them.'},
    {type:'table',head:['If this is low…','…the problem is usually','…and the work happens'],rows:[
      ['<strong>Attendance</strong> — they don\'t come','Scheduling, family, motivation, a course that stopped feeling relevant','<strong>Outside</strong> the lesson — reach out, flag it, involve the family or Teaching Ops'],
      ['<strong>Classroom Presence</strong> — they come but aren\'t there','Facilitation — the room is passive, participation sits with one or two students, or technical problems get in the way','<strong>Inside</strong> the lesson — how you open, who you call on, how you close'],
    ]},
  ]},
  {t:'🔍 What Causes a Student to Miss Class?',cards:[
    {type:'twocol',left:{h:'🌦️ External (outside your control)',items:['Vacations','Illness','Family issues','National holidays']},right:{h:'🎯 Internal (you can influence these)',items:['They\'re bored in class','They don\'t feel heard','They feel they\'re “not good” at this','They\'re confused and lost']}},
  ]},
  {t:'🔔 When Would You Hear From Us?',cards:[
    {type:'text',b:'Your students\' risk groups are one thing. What would make us reach out to <strong>you</strong> is another — and it is three situations, and nothing else.'},
    {type:'table',head:['You\'ll hear from us when…','Because','What you\'ll get'],rows:[
      ['Your HPR is below target or your LPR is above it','Too few of your students are fully present, or too many are barely there','A training on running the room — openings, participation, closings'],
      ['Two or more of your students have two or more unexplained (red) absences — or, once you have 10 or more students, more than half your roster is carrying one','Absences are repeating and nobody knows why. One student with one red absence never puts you on the list — the pattern does','A training on the absence protocol — contacting families, recording the reason, extra lessons'],
      ['One student has three or more red absences, or two or more students have four or more yellow each','Those students are close to leaving, whatever your overall numbers look like. This is the one case where explained absences count too, because four in a row is a pattern in itself','The names, immediately, and a training — this one is urgent'],
    ]},
    {type:'good',txt:'And what it is not: a message is not a warning and not a step in any disciplinary process. No decision about you is made by a number — the platform decides where we look first, then a person talks to you. If the data looks wrong to you, saying so is useful; some of it will turn out to be a recording gap rather than a teaching problem, and we would rather hear that from you than guess.'},
  ]},
  {t:'⛓️ How does this affect you as a tutor?',cards:[
    {type:'hi',h:'One missed class rarely stays just one missed class',b:'Misses a class → falls behind → gets discouraged → stops seeing the point → leaves. And a group that loses two or three students stops feeling like a group to the ones who stay.<br><br>Every step earlier you interrupt that chain is a student kept — which is the only reason any of this is measured.'},
    {type:'text',b:'The good news: the internal causes — the ones we <em>can</em> change — are the focus of the rest of this training.'},
  ]},
 ]},

{id:2,emoji:'🧭',title:'Lesson Structure & Attendance',desc:'Why a consistent lesson routine is one of the strongest attendance levers, and the nine phases that make up every Kodland lesson.',obj:'Understand why a consistent lesson structure drives attendance, and learn the nine phases that make up a Kodland lesson.',color:'#D3FF5F',
 sections:[
  {t:'💡 Why This Matters',cards:[
    {type:'text',b:'Something correlates strongly with attendance: keeping a consistent routine and structure in your lessons. Consistency is the point. Once a student learns your rhythm, they stop spending energy figuring out “what happens now?” and spend it on learning instead. Run the same structure every time until it\'s second nature — for you and for them. A predictable lesson feels like a safe lesson, and a safe lesson is one a student wants to come back to.'},
    {type:'text',b:'Here\'s how a Kodland lesson is structured, phase by phase, and how keeping that order intact protects your attendance numbers.'},
  ]},
  {t:'🌅 The Beginning: Four Phases',cards:[
    {type:'phases',items:[
      {num:1,ic:'👋',h:'Warm-Up',bg:'#bed2ff',bd:'#5477d9',b:'A quick question or tiny challenge that shifts the student into "lesson mode" — and a key community-building moment, making them feel like part of something, not just a name on a schedule.',src:'https://drive.google.com/file/d/1fMWyd6bfCcUauqIIaNldojVuHYg6J9JR/view?usp=sharing'},
      {num:2,ic:'📖',h:'Previous Lesson Revision',bg:'#f5d6fe',bd:'#b15fd1',b:'Briefly revisit what was learned last time, letting the student recall it in their own words. That sense of "I remember this" builds real confidence — and confidence is a big reason a student stays engaged and wants to return.',src:'https://drive.google.com/file/d/1J1jijTw8bj8l9yw9aMNXp9zHwxEbkWbY/view?usp=sharing'},
      {num:3,ic:'📋',h:'HW Check',bg:'#dcf5b8',bd:'#7cb342',b:'Go through the homework together. This is where you catch misunderstandings, praise effort, and show the student their work is genuinely seen.',src:'https://drive.google.com/file/d/1H2Awetu6fkoatv2RMonUeBawgK7tsR3e/view?usp=sharing'},
      {num:4,ic:'🎯',h:'Lesson Goal',bg:'#ffdfb3',bd:'#e08a2e',b:'State plainly what today is about. A clear goal gives the lesson direction — a student who doesn\'t know what today is "for" disengages quickly.',src:'https://drive.google.com/file/d/1cuqULcb1jxkwV_uepi-dnxFdx3FB41Si/view?usp=sharing'},
    ]},
    {type:'agefriendly',intro:'Take a look at examples of how you can phrase things at the start of a lesson based on age:',younger:'"I\'m so glad you\'re back! Ooh, what\'s that in the background — is that a new Minecraft plush? I love that you\'re adding new friends to your collection! You know what would be awesome? Building a copy of your new buddy in Minecraft today."',older:'"Hey, good to see you again — how was your weekend? ... Yeah, school can get really intense with so many projects going on. Actually, we\'re heading into an AI and presentations module soon, and I think you\'ll like it — it\'ll help you speed through the repetitive parts of a project so you can spend more time on the part you\'re actually good at: bringing your ideas to life."'},
  ]},
  {t:'🎨 The Middle: Theory & Practice',cards:[
    {type:'text',h:'5 · Theory & Practice — the heart of the lesson',b:'Between the lesson goal and the closing phases sits the longest stage, where new material is taught and immediately used. Keep theory in small chunks — one concept, then hands-on work with it — and model first: demonstrate the technique on your screen before students try it on theirs. In a design course, the practice stage is where students actually create, so protect that time fiercely; a lesson where kids only watched you design/coding is a lesson where nobody designed/coding. This is also the part of the lesson students look forward to most — protect it, and you protect the reason they show up.'},
  ]},
  {t:'🏁 The End: The Mirror',cards:[
    {type:'text',b:'The closing four phases echo the opening ones in reverse — the lesson ends the way it began, giving students a satisfying sense of closure and rhythm. This “circular” shape is what makes a lesson feel complete rather than just stopping when time runs out, and a lesson that feels complete is one a student leaves without loose ends pulling them away.'},
    {type:'phases',items:[
      {num:1,ic:'📋',h:'Lesson Summary',bg:'#bed2ff',bd:'#5477d9',b:'Recap what was covered, but let the student summarize it too — their own words reveal what actually landed.',src:'https://drive.google.com/file/d/1jNZGDMnRYh83xGd2NVHrZTdgXLagi2GZ/view?usp=sharing'},
      {num:2,ic:'📖',h:'HW Assignment',bg:'#f5d6fe',bd:'#b15fd1',b:'Assign homework with crystal-clear instructions on what to do and how. Vague homework is homework that won\'t get done.',src:'https://drive.google.com/file/d/1qOYvENqjiYlwRaFvDb0A7W6JYgWPCjJc/view?usp=sharing'},
      {num:3,ic:'▶️',h:'Next Lesson Preview',bg:'#dcf5b8',bd:'#7cb342',b:'Tease what\'s coming next: “Next time, we\'ll make our character move just like in real life!” Keeps the student emotionally invested in the story you\'re building together — not just the task list.',src:'https://drive.google.com/file/d/17bE6JdZmDFJ_igrWYhc7fnpD39b-k-2K/view?usp=sharing'},
      {num:4,ic:'✨',h:'Wrap-Up',bg:'#ffdfb3',bd:'#e08a2e',b:'End on a high: celebrate what the student created, and send them off feeling like a valued part of the class, not just done with a task. The last 30 seconds are what they weigh, consciously or not, when deciding whether to show up next time.',src:'https://drive.google.com/file/d/1OTYSh07wSosjgsHFD05YvccD3NY2CgsX/view?usp=sharing'},
    ]},
    {type:'agefriendly',intro:'Take a look at examples of how you can phrase things at the end of a lesson based on age:',younger:'"Look at that — your dragon can finally fly across the whole screen! You worked SO hard on that jump code, I could tell you weren\'t going to give up. Next class we\'re going to make it breathe fire, so get ready!"',older:'"That\'s a clean solution — you debugged that collision issue faster than I expected. Next class we\'ll start layering in the physics for it, so hang on to that logic, it\'s going to come in handy."'},
  ]},
  {t:'🪞 Summary: Mirror Structure',cards:[
    {type:'mirrorSummary',img:'Images/Mirror_Structure_ENG.png',caption:'The lesson ends exactly as it began, giving students a sense of closure, continuity, and rhythm.',tipH:'⭐ Tip',tipB:'Sticking to this routine and maintaining predictability is a very useful tip if your course is for children ages 8–9 or if you have students who are anxious and get frustrated by change.'},
  ]},
 ]},

{id:3,emoji:'🤝',title:'Building a Bond With Your Students',desc:'Small talk, feedback that actually lands, and how to make every student feel like part of the group.',obj:'Learn how to build a valuable bond with your students that makes them want to come back.',color:'#D3FF5F',
 sections:[
  {t:'💙 Why This Matters',cards:[
    {type:'text',b:'At Kodland, our students take an extracurricular course — it\'s not mandatory. Unlike school, nothing forces them to come back. That\'s why the bond with the tutor and the group isn\'t a nice extra: it\'s the reason they return. Here are the keys and everyday opportunities you have in class to build it.'},
  ]},
  {t:'👋 Small Talk at the Start of Class',cards:[
    {type:'img',src:'Images/image1.png'},
    {type:'hi',h:'The first 5 minutes change everything',b:'A warm start makes a student feel safe. A safe student is one who tries, fails, learns, and comes back.'},
    {type:'doavoid',left:{h:'✅ What to Do',items:['Greet warmly: “I\'m so glad you\'re here”','Ask something personal, briefly','Introduce the lesson with energy: “Today we\'re building something amazing”','Reinforce psychological safety: “Mistakes are part of learning”']},right:{h:'❌ What to Avoid',items:['Jumping straight into content: “Let\'s open the activity”','Skipping the greeting','Not explaining what you\'ll do or why','Rushing or sounding stressed']}},
    {type:'cute',h:'Tip',b:'Those minutes of chat — at the start, at the end, or during an activity — are what show a student they\'re a person, not just another name on your class list.'},
    {type:'video',vkey:'m2-smalltalk',h:'Take a look at an example of a real class',src:'https://drive.google.com/file/d/1NtrwskCgGVzSy97z-VaDwtMNEfchUiTk/preview'},
  ]},
  {t:'💬 Constructive Feedback',cards:[
    {type:'img',src:'Images/image2.png'},
    {type:'text',b:'Feedback is another key piece of building that connection. It\'s not about making students feel like everything they do is perfect — it\'s about guiding their learning process and helping them understand exactly what they\'re doing well. A generic compliment like “nice” or “I like it”, repeated too often, starts to sound like the opposite: I don\'t really care about your work, it\'s not that important. Let\'s show our students we know exactly what we like about their work — because we\'re really looking at it.'},
    {type:'text',h:'A simple scheme for better feedback',b:'Use this three-step flow, in order, to give more constructive feedback:'},
    {type:'flow',steps:[
      {ic:'🔦',h:'Highlight',b:'Point out one decision the student made — explain why it works in terms of its effect, not its quality.<br><br><em>Example:</em> “You set up the button so it only changes color when the player hovers over it exactly where you want — that small detail makes the whole page feel intentional.”',color:'blue'},
      {ic:'❓',h:'Ask',b:'Ask with genuine curiosity, treating the student as the authority on their own work.<br><br><em>Example:</em> “Did you imagine them as a group from the start, or did one lead to the next as you were drawing?”',color:'coral'},
      {ic:'➡️',h:'Activate',b:'Offer a real, open choice for what comes next.<br><br><em>Example:</em> “Want to give them a story — who they are, where they\'re headed? Or if you feel it\'s already complete, that\'s valid too.”',color:'green'},
    ]},
    {type:'table',h:'⚠️ Common feedback mistakes',tone:'danger',head:['Mistake','Why you shouldn\'t do this'],rows:[
      ['“Great job!” with no specifics','The student can\'t repeat a success they don\'t understand'],
      ['Focusing on the result, not the process','Creates dependence on the tutor\'s judgment'],
      ['Correcting without guiding','Removes agency — the student waits for corrections instead of building their own judgment'],
      ['Several corrections at once','Cognitive overload — at this age, students process 1–2 pieces of feedback at a time'],
    ]},
    {type:'video',vkey:'m2-feedback',h:'Take a look at an example of a real class',src:'https://drive.google.com/file/d/1dju7fHKNzTYMTnAesr1I_KKvl1jL8BNL/preview'},
    {type:'agefriendly',intro:'Take a look at examples of how you can give feedback on a project based on age:',younger:'"Wait, your character\'s cape is actually moving when they jump — did you figure that animation trick out on your own? That\'s such a cool detail, it makes the whole thing feel alive!"',older:'"The way you structured that function so it\'s reusable across levels — that\'s actually how a lot of real game studios approach it. Where\'d the idea come from?"'},
  ]},
  {t:'🎉 Inviting Participation & Building Camaraderie',cards:[
    {type:'img',src:'Images/image3.png'},
    {type:'text',b:'Students don\'t come back to class only because they like the topic — they come back because they\'ve found a safe space to talk, be themselves, meet peers their age with similar interests, and build the same dreams. One of the ways we build that space is by encouraging participation and camaraderie in a friendly, genuine way:'},
    {type:'hi',h:'💡 A child\'s brain calms down when an authority figure pays real attention',b:'If you don\'t actively notice their progress, they feel invisible — and an invisible student is one who stops looking forward to class.'},
    {type:'doavoid',left:{h:'✅ What to Do',items:['Name specific wins: “Lucas, I noticed your logic is really clean”','Use chat and reactions so everyone can join in real time','Celebrate effort: “You tried three different approaches — that\'s strategic thinking”','Rotate your attention during independent work — don\'t leave anyone unchecked']},right:{h:'❌ What to Avoid',items:['Generic praise: “Good job, everyone”','Only noticing the ones who finish fast','The same pace for the whole group (bores the fast ones, rushes the slow ones)','Leaving slower students without support']}},
    {type:'text',h:'Ways to participate',b:'Not everyone feels comfortable the same way. All of these are valid, as long as they follow class rules: camera, mic, or chat only; backgrounds and reactions that reflect their personality; open questions for some, closed ones for others.'},
    {type:'list',h:'How to build camaraderie',items:[
      'Create small group rituals — a greeting, a phrase, or a “challenge of the week” unique to your class',
      'Invite students to comment (respectfully) on a classmate\'s work: “What did you like about what [name] made?”',
      'Celebrate group wins, not only individual ones',
      'Use pair or small-group work when the activity allows it',
      'Remember details between classes — if someone mentioned something last week, ask how it went',
    ]},
    {type:'video',vkey:'m2-participation',h:'Take a look at an example of a real class',src:'https://drive.google.com/file/d/1-L7C70hKSGYI8QhkPpb7fvrhJG1-vchf/preview'},
  ]},
  {t:'⚖️ Balancing Skill Levels',cards:[
    {type:'img',src:'Images/image4.png'},
    {type:'text',b:'Not every student moves at the same pace — and that\'s completely normal. The goal isn\'t to make anyone stand out or feel left behind; it\'s to let each student progress at their own speed, without anyone feeling singled out.'},
    {type:'twocol',left:{h:'🚀 For Faster Students',items:['Offer extra challenges that take their work to the next level','Turn them into class helpers or “monitors” for a moment','Encourage them to ask themselves deeper questions about their own work','Give them room to explore beyond the base activity']},right:{h:'🌱 For Students Who Need More Time',plain:true,items:['Offer direct support and check in more often','Simplify steps — break the task into smaller pieces','Celebrate progress, not just the finished result','Give them the time they need without rushing the group']}},
    {type:'cute',h:'Remember',b:'We all start with the basics. Normalize mistakes — the goal is progress at each student\'s own pace, never comparison between students.'},
  ]},
 ]},

{id:4,emoji:'✨',title:'Creating Unforgettable Classes',desc:'Visual material, modeling before practice, checking for understanding, and closing with anticipation.',obj:'Learn the four habits that turn an ordinary class into one students don\'t want to miss.',color:'#D3FF5F',sortGame:true,
 sections:[
  {t:'🌟 What Makes a Class Unforgettable',cards:[
    {type:'text',b:'An unforgettable class comes from an experience outside the ordinary: a tutor who listens, a practice where the student\'s opinion matters, challenges for those moving faster and support for those who need more help, and a class where mistakes aren\'t judged — they\'re learned from.'},
    {type:'img',src:'Images/image5.gif'},
    {type:'text',b:'To understand what makes a class unforgettable, we looked at which quality aspects correlate most strongly with the best classes. Here they are:'},
  ]},
  {t:'🖼️ Visual Material',cards:[
    {type:'text',b:'Visuals aren\'t decoration — they\'re what turns an abstract idea into something understood in seconds. Before explaining with words, show an example, an image, or a live demo on screen. Visual material is a key tool in virtual learning environments — it takes teaching to another level. Students don\'t just learn by doing, they learn by seeing. This connects strongly with the next habit:'},
  ]},
  {t:'🎬 Model Before Practice',cards:[
    {type:'text',b:'Never ask a student to do something they haven\'t seen done first. Modeling the process step by step — thinking out loud as you go — gives them a clear map of what\'s expected, and cuts down the frustration of “I don\'t know where to start.” Before practice starts, give students a clear signal of what\'s coming: “Everyone, eyes on my screen in the classroom — I\'m going to show you how this works, and once I\'m done, you\'ll do it yourselves.” Clear expectations about the order of the class — and what happens right after the tutor models — keep the group focused and reduce anxiety about what comes next.'},
    {type:'video',vkey:'m3-model',h:'Take a look at an example of a real class',src:'https://drive.google.com/file/d/1H4DOo4YkqXg3udOFVYP2hfb3E-mmz6pI/preview'},
    {type:'agefriendly',intro:'Take a look at examples of how you can model this phase based on age:',younger:'"Okay everyone, on the count of 3 we\'re all racing to the Classroom tab — whoever\'s there gives me a reaction so I know you\'re ready to listen. Perfect — Maria\'s here, Pedro\'s here, I saw your reaction Alejandra, you made it too! Awesome, now that we\'re all here, first we\'re going to watch how I do it, and once we\'ve seen it, you\'ll get to try it yourselves. Let\'s see those thumbs up on camera!"',older:'"Alright everyone, now we\'re moving into the theory and practice part. First I\'m going to show you how it\'s done before you try it on your own — for that I need everyone in the Classroom tab watching my screen, so please react once you\'re there. Perfect, now that I can see we\'re all set, let\'s get started!"'},
  ]},
  {t:'✅ Check for Understanding',cards:[
    {type:'text',b:'Don\'t wait until the end of class to discover something wasn\'t clear. Use different methods depending on the group: quick chat questions, emoji reactions, or asking students to share their screen. Checking in often also shows students that you care whether they actually learn — not just whether they moved on.'},
    {type:'agefriendly',intro:'Take a look at examples of how you can check for understanding based on age:',younger:'"This is what each of you is going to do now on your own computer. Remember, we only have 10 minutes to finish the character\'s face. To make sure we\'re all clear on what to do, Andres, can you tell the class what we need to do in the next 10 minutes? Okay class, if you feel as sure as Andres about what we\'re doing, react with the heart emoji. And remember, if you have questions you can ask in the chat or on the mic — questions are important and I\'m always happy to answer them."',older:'"Alright everyone, that\'s everything we need to do to finish our Python bot. I\'d like to know if it all made sense — please react, or feel free to answer out loud. If you have any questions, go ahead and ask so we can clarify a concept or confirm anything that might still feel a little unclear. Remember, there\'s no such thing as a silly question."'},
  ]},
  {t:'🚀 Build Anticipation for Next Class',cards:[
    {type:'text',b:'Close class by connecting what\'s coming next to something your students actually care about. A great closing line does more work than a great opening one — it\'s the reason a student wants to come back.'},
    {type:'list',h:'Examples that land',items:[
      '<strong>Graphic design:</strong> “Next class we\'re entering the web page module — for everyone who told me on day one they\'d build a page for their favorite band, that moment is almost here.”',
      '<strong>Programming:</strong> “Next lesson you\'ll learn to save progress — so the game you\'ve been building will finally remember who won.”',
      '<strong>Roblox / Minecraft:</strong> “Next class is the first time you\'ll publish something other players can actually see. Get ready.”',
    ]},
    {type:'cute',h:'Tip',b:'A good closing isn\'t just “see you next time” — it\'s planting the seed of something they want to see finished themselves.'},
    {type:'video',vkey:'m3-anticipation',h:'Take a look at an example of a real class',src:'https://drive.google.com/file/d/119ytsWF3qk_Tp6qi1md4xbouEhWLGGz9/preview'},
    {type:'agefriendly',intro:'Take a look at how you can tailor anticipation for next class based on age:',younger:'Tie it to their personal interests — favorite video games, movies, dreams they want to achieve at Kodland, short-term projects they\'ve mentioned wanting to build, or shows they\'re into.',older:'Tie it to their professional future — short- or long-term project goals, and questions they\'ve asked earlier in the course that it\'s now time to explore in depth.'},
  ]},
 ]},

{id:5,emoji:'📝',title:'Homework and Attendance',desc:'Explain, remind, highlight, and review — the four homework habits that reinforce attendance.',obj:'Turn homework from a metric into another way to strengthen your bond with students and their families.',color:'#D3FF5F',
 sections:[
  {t:'🎯 Homework Is More Than a Metric',cards:[
    {type:'text',b:'Handled well, homework reinforces the bond, gives you a second chance at feedback, and shows students — and their parents — that their progress matters outside the live class.'},
    {type:'img',src:'Images/image6.png'},
  ]},
  {t:'📣 Explain the Homework',cards:[
    {type:'text',b:'Don\'t mention it in passing at the end of class. Explain what to do and, above all, <strong>why</strong> — how it connects to what they just learned. Homework without a clear purpose is the first thing forgotten.'},
    {type:'video',vkey:'m4-explain',h:'Take a look at an example of a real class',src:'https://drive.google.com/file/d/1qOYvENqjiYlwRaFvDb0A7W6JYgWPCjJc/preview'},
    {type:'agefriendly',intro:'Take a look at examples of how you can explain the homework based on age:',younger:'"Okay, for homework you get to design your OWN power-up — like a mushroom or a star, but totally your own idea. I can\'t wait to see what you come up with!"',older:'"For homework, you\'ll be adding a scoring system to what we built today — it\'s the same logic as today\'s lesson, just applied to a new feature. Should take you 20–30 minutes."'},
  ]},
  {t:'⏰ Remind About the Homework',cards:[
    {type:'text',b:'A short reminder close to the deadline dramatically improves submission rates. It can be as simple as a message, or a quick mention at the start of the next class: “Has anyone already started the project?”'},
  ]},
  {t:'🌟 Highlight the Homework During Class',cards:[
    {type:'text',b:'Give it visibility — and make sure every student gets a moment, not just the strongest project. Look for something specific and positive in each student\'s work, even if it\'s a single sentence: “I saw you fixed that bug on your own, that\'s not easy!” If your group is large and there isn\'t time to go through every submission live, highlight something collective for everyone who turned it in: “90% of the group brought their homework complete — that commitment shows.”'},
    {type:'cute',h:'This is not a place for judgment',b:'The goal is to motivate — never to make a student feel bad or afraid because they didn\'t submit.'},
  ]},
  {t:'🔎 Review the Homework',cards:[
    {type:'text',b:'Reviewing isn\'t just marking “done” or “not done.” It\'s a chance to leave a detailed comment that parents and students can read — reinforcing that there\'s a real person, not just a platform, following their progress.'},
    {type:'video',vkey:'m4-review',h:'Take a look at an example of a real class',src:'https://drive.google.com/file/d/1H2Awetu6fkoatv2RMonUeBawgK7tsR3e/preview'},
  ]},
 ]},

{id:6,emoji:'📞',title:'What to Do When a Student Misses Class',desc:'What you select in Back Office, how you personally make an absent student feel missed, and when Customer Service steps in instead.',obj:'Know exactly what to select in Back Office and when, how to reach out so a student feels missed and supported, and know when an administrative issue or an unresponsive family means it\'s time to loop in Customer Service.',color:'#D3FF5F',
 sections:[
  {t:'🎯 What You Select, and When',cards:[
    {type:'text',b:'Before anything else: two clicks, and the whole metric depends on them. Module 1 explained what red and yellow mean. Here is exactly when you choose which.'},
    {type:'redyellow',left:{h:'🔴 Select RED when…',items:['The student did not appear and nobody told you why. That is the only case.','Red is not a harsher label for the same event — it means we do not know what happened, which is what makes it the most dangerous state a student can be in.','Nobody can help a student whose problem is invisible.']},right:{h:'🟡 Select YELLOW when…',items:['Someone told you a reason — before or after the lesson. Then pick which of the six reasons it was, if you know it.','Those options are not paperwork: they are part of how the pattern gets understood, whether it\'s you or Customer Service who acts on it.','Five seconds from you, and a pattern that can be acted on.']}},
    {type:'list',h:'The six reasons in BO',p:'Pick the closest one honestly — some expand into a more specific option once selected.',items:[
      '🏥 <strong>Health issues</strong>','📚 <strong>Content issues</strong>','✈️ <strong>Vacation:</strong> traveling, school vacation, or holidays','💻 <strong>Technical issues:</strong> student\'s computer, the Kodland platform or Classroom, a power outage, or an internet connection problem','🗓️ <strong>Scheduling issues:</strong> moved to another group, or the lesson was rescheduled','📝 <strong>Other:</strong> school load / exams / homework, a family reason, or no specific reason shared (a comment is required)',
    ]},
    {type:'warnbox',h:'And the line that protects all of it',b:'An absence you recorded honestly is never held against you. The only absence that hurts your numbers is the one nobody explained.'},
    {type:'simulation',title:'BO Simulation — Marking Attendance',src:'Simulacion_BO_Attendance_1.html'},
  ]},
  {t:'🔁 Follow Up',cards:[
    {type:'hi',h:'Make sure they know they were missed',b:'A message from you — not just an automated one — is what makes an absence feel noticed instead of invisible. A short, warm message goes a long way: you were missed today, here\'s where to find the recording, and the practice activities are there whenever you\'re ready — framed as something useful, not an obligation.'},
    {type:'list',items:[
      'Send a short message pointing to the recording and any extra practice activities on the platform — an opportunity to catch up, not a chore.',
      'When the student returns, make it personal: ask if they got a chance to watch the recording, or if they need help finding it.',
      'This part is yours. Customer Service steps in only for administrative issues, or if a family stops responding to your messages altogether.',
    ]},
  ]},
  {t:'⏱️ Timing: What the Count Actually Triggers',cards:[
    {type:'text',b:'These thresholds don\'t just trigger something you do — they also trigger consequences for the student, automatically, on Customer Service\'s side.'},
    {type:'table',h:'What changes as absences add up',head:['Count','What happens to the student','Your part'],rows:[
      ['1st absence','Nothing automatic yet','Message the student directly — recording, practice activities, a genuine "we missed you"'],
      ['2nd–3rd absence','The student becomes eligible for an extra lesson, which CS can offer the family','Keep messaging directly; flag it to Customer Service if the family has gone quiet'],
      ['4th absence or more','The student risks losing access to recordings, and moves closer to being withdrawn from the course','Loop in Customer Service — this is now an administrative matter'],
    ]},
    {type:'warn',txt:'The trigger for Customer Service isn\'t the absence count on its own — it\'s an administrative issue, or a family that stops answering you. Up to that point, this stays yours.'},
  ]},
  {t:'👨‍👩‍👧 Talking With Parents',cards:[
    {type:'imgtext',img:'Images/WhatsApp_module_6_ENG.png',items:[
      'Be kind and understanding, especially if the absence was due to illness or a family issue.',
      'If there\'s extra material available in the course, let them know.',
      'When the student does attend, use the moment to share their achievements in class with the parents.',
      'Warmth costs nothing and it is the whole difference between a family that stays engaged with the course and one that quietly stops replying.',
    ]},
    {type:'warnbox',h:'⚠️ What You Must Never Do',b:'Never suggest to a family that the student take a break from the course. Never discuss pricing with parents — that\'s Sales\' job. Never offer a 1-to-1 lesson without approval. And never inform a family about a cancellation or postponement without your TL\'s permission first.'},
  ]},
  {t:'📋 What to Log in Back Office',cards:[
    {type:'list',h:'Now a short checklist — the mechanism itself is in the first section above',items:[
      'Set the absence type and the reason. Yellow plus the matching reason from the six groups if you were told why; red if nobody told you anything.',
      'Add a comment with anything relevant you know. Short is fine — this is what Customer Service reads if the case reaches them.',
    ]},
  ]},
  {t:'🔀 And Then? Two Ways This Goes',cards:[
    {type:'text',b:'You have marked the absence and sent your message. From here the situation goes one of two ways, and they need different things from you.'},
    {type:'table',h:'They come back vs. they don\'t',head:['','✅ They come back','❌ They don\'t'],rows:[
      ['<span class="rowic">⚡</span>Straight away','Show them you noticed they were gone — warmly, and privately, not in front of the group.','Send a second message, on a different note if the first went unanswered — still you, not Customer Service.'],
      ['<span class="rowic">➡️</span>Then','Watch their presence, not just their attendance. If they turn up but stay at 40% in the room, that\'s Modules 2 to 4, not this one.','If the family goes quiet altogether, or it becomes an administrative matter, that\'s when Customer Service steps in.'],
      ['<span class="rowic">🧑‍🤝‍🧑</span>Who else you involve','Nobody, unless an extra lesson is worth flagging.','Customer Service — but only once it\'s gone from "a student I\'m following up with" to "a family I can\'t reach."'],
      ['<span class="rowic">👨‍👩‍👧</span>The parents','Share one concrete thing the student did in the lesson they came back to.','Keep it warm and low-pressure — you\'re still the one they hear from first.'],
    ]},
    {type:'redbox',h:'They came back, but they\'re still not really there.',b:'This is the most common outcome of all, and it is easy to file as solved because attendance recovered. It isn\'t solved: the student is now in the room and disengaged, which is a facilitation problem, not an absence problem.<br><br>That case belongs to Modules 2, 3 and 4 — how you open, who you call on, how you close.'},
  ]},
  {t:'🪜 If It Escalates: The Extra Lesson',cards:[
    {type:'text',b:'Requesting an extra lesson isn\'t a flow you run yourself here — <strong>Customer Service creates the request</strong> once the thresholds above are met.'},
    {type:'text',h:'🖥️ Try It Yourself',b:'Practice the part that\'s yours — marking attendance accurately — and see exactly what\'s already logged on a student\'s profile, so you know what Customer Service (or a colleague) has already tried:'},
    {type:'simulation',title:'BO Simulation — Marking Attendance & Reading CS Notes',src:'Simulacion_BO_Attendance_Simplified.html'},
  ]},
  {t:'🕳️ The Student Who Never Showed Up At All',cards:[
    {type:'hi',h:'This isn\'t a "missed class" — it\'s a different problem',b:'Some students never connect to a single lesson from day one. Treat a no-show on lesson one as an immediate red flag, not something to wait out.'},
    {type:'text',b:'Mark it red — nobody told you anything — and send that first "we missed you" message yourself, same as any other absence. If the family never responds at all, that\'s when Customer Service takes over.'},
  ]},
 ]},
];
let CHECKLIST=[
  'Greet and connect before teaching — the first 5 minutes matter.',
  'Build a real bond — small talk, genuine curiosity about their world, and remembering details between classes.',
  'Create a safe, judgment-free environment where mistakes are normal and every student can grow at their own pace.',
  'Give feedback that highlights the process, not just the result.',
  'Balance skill levels — challenges for faster students, support and simpler steps for those who need more time.',
  'Encourage participation and camaraderie in a friendly, genuine way — students come back for the group, not only the topic.',
  'Check for understanding before moving on.',
  'Close class by building anticipation for what\'s next.',
  'Explain, remind, highlight, and review homework — every step counts.',
  'If a student misses class, follow up with them and with their family.',
  'Talk to parents with empathy, and loop in your TL before offering an extra class.',
];
let SELF_QUESTIONS=[
  'Did I greet my students warmly today, before jumping into the content?',
  'Have I given at least one piece of process-focused feedback this week — not just “great job”?',
  'Is there a student in my group who might be feeling invisible right now?',
  'Am I giving my faster students real challenges, and my slower students real support — without singling anyone out?',
  'Did I build anticipation for the next class before saying goodbye?',
  'Have I reached out to every parent whose child missed a class recently?',
  'Do my students feel this is a safe space to be themselves and make mistakes?',
];
let QUIZ={
1:[
 {q:'What does HPR measure?',opts:['The share of your students with Classroom Presence below 50%','The share of your students with Classroom Presence at 75% or above','The share of your students who completed their homework'],c:1,fb:'HPR (High Presence Rate) is the share of your students at 75% presence or above — everyone in 🟢 Healthy or 🔵 WATCH. The share below 50% is LPR.'},
 {q:'A student tells you they feel like they\'re "not good" at coding. Which category does this fall into?',opts:['An external cause, since it\'s about the subject, not the tutor','An internal cause — one you can influence through feedback and encouragement','Neither — it\'s a personality trait, not a real driver of attendance'],c:1,fb:'Feeling "not good" at the subject is one of the internal causes — the ones you can shift through how you teach and give feedback.'},
 {q:'A student is marked "attended" in Back Office, but the classroom log shows they were only connected for 40% of the lesson. How does this count?',opts:['As Present for both measures, since the BO record always overrides the classroom log','As Attendance (BO), since the lesson was recorded as attended — but NOT as Present for Classroom Presence, since 40% is below the 50% line','As an absence for both, since 40% doesn\'t meet either threshold'],c:1,fb:'Attendance (BO) and Classroom Presence are tracked separately: this student counts toward Attendance, but not toward Classroom Presence, since they never crossed the 50% line.'},
 {q:'Which of the following does BO Attendance actually track?',opts:['Whether a scheduled lesson happened and the student showed up, according to Back Office','How long the student stayed connected in the virtual classroom','The student\'s score on homework and classwork'],c:0,fb:'BO Attendance simply confirms whether a scheduled lesson happened and the student showed up — how engaged they were is a separate measure, Classroom Presence.'},
 {q:'In Back Office, what turns a red (unexcused) absence into a yellow one?',opts:['Once the reason becomes known, changing the absence to yellow and selecting that reason','72 hours passing without any action','Leaving a comment in Back Office, without changing the absence type'],c:0,fb:'What turns a red absence yellow is changing the type and picking the reason once it\'s known — whether you found out directly or Customer Service passed it along. A comment on its own, without changing the type, leaves it red.'},
 {q:'One of your students has one announced (yellow) absence and Classroom Presence of 91%. Which group are they in?',opts:['ALERT — any absence moves a student into a risk group','WATCH — one absence is an early warning','Healthy — one explained absence with strong presence is not a risk signal'],c:2,fb:'One yellow absence with presence above 85% leaves a student Healthy. It takes two yellows to reach ALERT. An announced absence is a situation the family is managing — it is not a black mark on you or on them.'},
],
2:[
 {q:'A student joins with camera on but stays visibly withdrawn — quiet, staring at the desk. How do you start?',opts:['You greet them warmly, ask a brief personal question about their week, and once they respond, ease into today\'s plan.','You open with an energetic greeting and move straight into recapping last class\'s project, trusting that the momentum of getting started will pull their attention back in.','You greet them and ask if everything\'s okay, then wait quietly for them to respond before deciding whether to start the lesson.'],c:0,fb:'A genuine personal check-in before diving in is what re-engages a withdrawn student — energy alone or a passive wait-and-see approach skips that step.'},
 {q:'Instead of asking students to recall last class, a tutor handles the opening differently. Which approach is strongest?',opts:['The tutor restates every detail from last class in full before moving into new material, reasoning that a complete recap guarantees nobody\'s left behind.','The tutor asks a two-minute question about what made last class\'s technique work, letting the student answer in their own words before building on it.','The tutor mentions in one sentence what was covered last class, then moves straight into today\'s objective without checking if it was retained.'],c:1,fb:'Retrieval — letting the student recall in their own words — builds memory and competence far more than re-explaining or rushing past it.'},
 {q:'True or false: ending a class right when time runs out — with no recap, no hint of what\'s coming next, and no acknowledgment of the student\'s effort — closes the lesson just as well as a strong Wrap-Up would.',opts:['True','False'],c:1,fb:'False — skipping the recap, the anticipation hook, and the acknowledgment throws away the same free attendance win a strong close protects.'},
 {q:'Which of these is <strong>NOT</strong> one of the four opening phases of a Kodland lesson?',opts:['A short warm-up that shifts the student\'s focus into lesson mode before content begins','A quick revisit of what was covered in the previous class before moving forward','A closing recap that celebrates what the student accomplished before ending the call'],c:2,fb:'That\'s a closing phase (Wrap-Up), not one of the four phases that open the lesson.'},
 {q:'A student submitted a poster for homework. How does the tutor review it?',opts:['The tutor notes the layout works well overall and encourages the student to "keep that same energy" on future projects.','The tutor highlights the specific choice that made the poster\'s focal point work, and asks what led the student to arrange it that way.','The tutor lists three things that could be stronger before moving to today\'s topic, without mentioning what worked.'],c:1,fb:'Highlighting a specific choice and asking about it shows the student their homework was actually looked at — vague praise or corrections-only feedback don\'t.'},
],
3:[
 {q:'A student joins with arms crossed and one-word answers when greeted. What\'s the best start?',opts:['You keep the greeting brief and move straight into today\'s activity, trusting that getting absorbed in the work will naturally lift their mood.','You acknowledge they seem a little off today, ask gently if everything\'s alright, and let them set the pace for how much they want to share.','You match their energy by staying quiet and businesslike, assuming they\'ll open up on their own once they feel less pressure to perform socially.'],c:1,fb:'Naming what you noticed and letting the student set the pace helps them feel safe — staying task-focused or staying passive both skip that step.'},
 {q:'During group work, one student hasn\'t spoken at all while two others chat actively. What\'s the best move?',opts:['You wait to see if they unmute on their own, reasoning that stepping in might feel like putting them on the spot.','You quietly invite them in through a low-pressure channel like the chat, letting them choose how much to engage without being singled out.','You ask the whole group if everyone\'s had a chance to share, hoping the quiet student takes the opening on their own.'],c:1,fb:'A direct but low-pressure, private invitation reaches the specific student — waiting it out or asking the group generically usually doesn\'t.'},
 {q:'Which of these is <strong>NOT</strong> one of the "what to do" practices for balancing skill levels?',opts:['Offering faster students a real extension challenge tied to today\'s objective','Giving students who need more time simpler steps and more frequent check-ins','Ranking students by how quickly they finish each activity so progress is visible to the group'],c:2,fb:'Ranking by speed invites comparison between students — the module is clear that progress should never be framed that way.'},
 {q:'Two students finish fast, three are stuck on step one. What\'s the tutor\'s move?',opts:['The two fast students move to a much harder, unrelated challenge, while the tutor spends the rest of class mainly with the other three.','The two fast students get an extension task tied to today\'s skill, while the tutor rotates between the other three to check in individually.','The tutor pauses the whole group to walk through the tricky step again for everyone, so the three who are stuck can catch up.'],c:1,fb:'An extension tied to the actual skill plus individual check-ins serves both groups at once — an unrelated challenge or a full-group pause leaves one side underserved.'},
 {q:'A student drew their first character. How does the tutor give feedback?',opts:['The tutor says the character\'s face turned out really well, calls them a talented artist, and encourages them to keep up the same quality.','The tutor gets genuinely excited about the specific choice made with the character\'s expression, tells them exactly why it works, and asks what gave them the idea — leaving the next step open.','The tutor notes the background hasn\'t been added yet, walks through what a finished background should include, and asks them to complete it next class.'],c:1,fb:'Genuine excitement over a specific choice, plus an open question, keeps the student\'s agency intact — better than praise about identity or a correction with nothing highlighted first.'},
],
5:[
 {q:'It\'s the last two minutes of class and you remember you need to assign homework. What do you do?',opts:['Quickly type the homework link in chat and say “okay do this for next class, bye!”','Take 30 seconds to explain what to do and why it connects to what we just learned today.','Explain in detail every single technical rule of the assignment, reading each requirement aloud.'],c:1,fb:'A clear purpose is what makes homework worth remembering — not a rushed mention or a wall of rules.'},
 {q:'You have a large group and only time to look at homework quickly before starting the new lesson. Most submitted, a few didn\'t. What do you do?',opts:['Highlight something collective for everyone who submitted: “90% of you brought your homework — that shows real commitment.”','Call out the names of the students who didn\'t submit so they feel motivated to do it next time.','Only showcase the single best project as the example everyone should aim for.'],c:0,fb:'The goal is motivation, not comparison or shame — a collective shout-out includes everyone who showed up.'},
 {q:'You\'re reviewing submitted homework and one student\'s project is technically correct but nothing special. What do you write?',opts:['Just mark it “done” with no comment — it met the requirements, that\'s enough.','Leave a long list of everything that could be improved, no positives mentioned.','Leave a short, specific comment noting one thing they did well and one gentle suggestion — something the parent could also read.'],c:2,fb:'Reviewing homework is a feedback opportunity, not just a checkbox — it\'s also a chance to reinforce the bond with students and parents.'},
],
6:[
 {q:'A student misses a lesson with no warning. What\'s your role in the first 24 hours?',opts:['Nothing — Customer Service handles all contact','Send the student a warm message yourself, with the recording and any practice activities — framed as an opportunity, not an obligation','Wait to see if Customer Service reaches out first, then follow up if they don\'t'],c:1,fb:'Making the student feel missed is your job here — a personal message with the recording and practice activities goes further than a system notification ever could.'},
 {q:'Why send a personal message about a missed lesson, when Customer Service will eventually step in anyway?',opts:['It\'s not really necessary — Customer Service will get there either way','So the student feels genuinely missed and supported, not just processed by a system — that\'s the difference between an automated flag and a person who noticed','Because Customer Service can\'t act until the tutor has messaged the student first'],c:1,fb:'Customer Service exists for administrative issues and unresponsive families — the personal message is what makes the student feel like a person was paying attention, not just a system.'},
 {q:'When does Customer Service actually step in?',opts:['As soon as a single absence happens','Once it becomes an administrative matter, or a family stops responding to your messages altogether','Never — this is entirely the tutor\'s responsibility'],c:1,fb:'Up to that point, following up is yours. Customer Service comes in for administrative issues or when a family has gone genuinely silent — not for every absence.'},
 {q:'Where do you check what\'s already been tried with a student before you follow up yourself?',opts:['You don\'t — there\'s no way to see that','In the student\'s profile, under Comments','Only by asking your TL directly'],c:1,fb:'Click the student\'s name to open their profile — Comments show what\'s already been logged, whether it was Customer Service or a colleague who left it.'},
 {q:'A student missed Tuesday\'s lesson with no warning, so you marked it red. On Thursday you learn the student had flu. What do you do?',opts:['Leave it red — it was unannounced at the time, and changing it afterwards would misrepresent what happened','Change the absence to yellow, select "Health issues", and add a comment with what you learned','Add a comment with what you learned and leave the absence type as it is'],c:1,fb:'Red means "we don\'t know why". Once you know, change the type, select the reason, and comment. A comment on its own leaves the absence red.'},
 {q:'A parent asks if their child can get an extra class. What do you tell them?',opts:['Schedule it directly since you know the family well','Let them know Customer Service manages extra-lesson requests','Tell them it\'s not possible'],c:1,fb:'Extra-lesson requests are created by Customer Service here, once the absence thresholds are met — not something you arrange directly.'},
],
};
let SORT_ITEMS=[
 {txt:'I model the process step by step, thinking out loud, before students try it.',type:'treasure',fb:'Exactly — modeling first gives students a clear map before they try it themselves.'},
 {txt:'I check in with quick chat questions or reactions throughout the class, not just at the end.',type:'treasure',fb:'Right — checking in throughout class catches confusion before it piles up.'},
 {txt:'I close class by connecting what\'s coming next to something my students actually care about.',type:'treasure',fb:'Yes — a strong hook at the end is often the real reason a student comes back.'},
 {txt:'I assume that if no one asks a question, everyone understood.',type:'trash',fb:'Silence isn\'t proof of understanding — students often stay quiet even when they\'re lost.'},
 {txt:'I end class with just “okay, see you next time, bye!”',type:'trash',fb:'A flat goodbye wastes the chance to build anticipation for the next class.'},
 {txt:'I skip visuals because “they already read the instructions.”',type:'trash',fb:'Reading instructions isn\'t the same as seeing them in action — visuals still matter.'},
];
const FINAL_EXAM=[
 {q:'A student joins class visibly quiet, giving one-word answers. What\'s the best way to start the lesson?',opts:['Skip straight to today\'s activity so they don\'t feel singled out','Take a moment for warm, genuine small talk before diving in','Ask them directly, in front of the group, why they\'re being so quiet'],c:1,fb:'A warm, low-pressure start is what helps a quiet student feel safe before anything else happens.'},
 {q:'Which of these is encouragement rather than praise?',opts:['“You\'re so talented!”','“I saw how carefully you built up those layers.”','“Perfect, amazing work!”'],c:1,fb:'Encouragement points at what the student actually did — the process — not at their identity.'},
 {q:'True or false: repeating a generic compliment like “nice job” too often can start to feel like you don\'t really care about the student\'s work.',opts:['True','False'],c:0,fb:'Exactly — generic praise loses meaning fast, and students notice.'},
 {q:'During independent work, two students finish quickly while three are still struggling. What should you do?',opts:['Move on once the fast ones are done, since most of the class is ready','Rotate your attention — check in with the students who are struggling without abandoning the ones who finished','Give the fast finishers extra credit and let the others catch up on their own'],c:1,fb:'Rotating attention is what keeps both groups engaged instead of leaving one of them behind.'},
 {q:'You\'re about to introduce a brand-new tool students have never used before. What\'s the right next step?',opts:['Give them the instructions and let them explore on their own','Model the process step by step before they try it themselves','Show a finished example and move straight to the assignment'],c:1,fb:'Modeling first gives students a clear map before they try it themselves.'},
 {q:'What\'s the main reason to build anticipation for the next class?',opts:['It fills time at the end of class','It\'s required by the platform','It gives students a real reason to come back'],c:2,fb:'A strong hook at the end is often the real reason a student shows up next time.'},
 {q:'True or false: checking for understanding should only happen at the very end of class, once the lesson is complete.',opts:['True','False'],c:1,fb:'False — check in throughout the class, not only at the end, so nothing slips by unnoticed.'},
 {q:'You have limited time to review homework for a large group. A few submitted outstanding projects, and several submitted basic work. What\'s the best approach?',opts:['Showcase only the best projects so students see what excellence looks like','Give each student a specific positive comment, and highlight something collective for everyone who submitted','Skip highlighting altogether since time is limited'],c:1,fb:'Every student gets a moment — individually if you can, collectively if time is tight. Never just the top project.'},
 {q:'Why is it important to explain the purpose of homework, not just assign it?',opts:['Because tasks without a clear “why” are the first thing students forget','Because it\'s a formal requirement from the platform','Because parents ask about it often'],c:0,fb:'A clear purpose is what makes homework worth remembering.'},
 {q:'A student has missed the last two classes and their parent hasn\'t reached out. What should you do first?',opts:['Wait for the parent to contact you','Reach out to the parent or guardian to check in and let them know the student was missed','Lower the student\'s engagement score and move on'],c:1,fb:'A proactive, caring check-in is always the first step.'},
 {q:'A parent asks if their child can get an extra class to catch up. What\'s the correct next step?',opts:['Schedule the extra class directly with the parent','Tell the parent it\'s not possible','Contact your TL first to review the case before proposing anything'],c:2,fb:'TL first, always — before anything is proposed to the parent.'},
 {q:'True or false: sharing the class recording and a quick homework recap with a student who missed class helps them stay on track and motivated.',opts:['True','False'],c:0,fb:'True — it keeps them from falling behind and losing motivation.'},
 {q:'Before proposing an extra class to a parent, a tutor should:',opts:['Contact their TL first','Decide alone and inform the TL after','Ask the student directly'],c:0,fb:'TL first, always — before anything reaches the parent.'},
];
